using System;using System.IO;
class LaunchOptionsTests {static void Assert(bool x){if(!x)throw new Exception("Assertion failed");}static void Reject(Action a){try{a();}catch(Exception){return;}throw new Exception("Expected refusal");}static int Main(){LaunchOptions.Validate("-force-d3d11 -screen-fullscreen 0");Reject(()=>LaunchOptions.Validate("%command% wrapper"));Reject(()=>LaunchOptions.Validate("a\nb"));Reject(()=>LaunchOptions.Validate(new string('x',1501)));string root=Path.Combine(Path.GetTempPath(),"launchoptions-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path.Combine(root,"config"));Directory.CreateDirectory(Path.Combine(root,"userdata/1/config"));try{File.WriteAllText(Path.Combine(root,"config/loginusers.vdf"),"\"users\" { \"76561197960265729\" { \"MostRecent\" \"1\" } }");File.WriteAllText(Path.Combine(root,"userdata/1/config/localconfig.vdf"),"\"UserLocalConfigStore\" { \"Software\" { \"Valve\" { \"Steam\" { \"apps\" { \"123\" { \"LaunchOptions\" \"-windowed -force-d3d11\" } } } } } }");Assert(LaunchOptions.SteamArguments(root,"123")=="-windowed -force-d3d11");Assert(LaunchOptions.SteamArguments(root,"456")==null);File.WriteAllText(Path.Combine(root,"config/loginusers.vdf"),"\"users\" { \"1\" { \"MostRecent\" \"1\" } \"2\" { \"MostRecent\" \"1\" } }");Assert(LaunchOptions.SteamArguments(root,"123")==null);}finally{Directory.Delete(root,true);}Console.WriteLine("PASS: active-account Steam arguments, missing app, ambiguous account refusal, multiline/length/wrapper refusal. No game launched.");return 0;}}
